		programInput.style('font-family', 'monospace');
		programInput.style('color', 'limegreen');
		programInput.style('font-size', '16px');
		programInput.input(updateShader);
		updateShader();
		p.noStroke();
	}

	async function updateShader() {
		try {
			program = programInput.value();
			// Make sure program is valid
			validateShader(vert, compileProgram(program));
			programShader = p.createShader(vert, compileProgram(program));
			p.shader(programShader);
			programShader.setUniform("width", p.width);
			programShader.setUniform("height", p.height);
			programShader.setUniform("size", size);
			programShader.setUniform("error", 0);
		} catch (e) {
			console.warn(e.toString());
			if (programShader) {
				programShader.setUniform("error", 1);
			}
		}
	}

	p.draw = () => {
		programShader.setUniform("(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))", p.mouseX);
		programShader.setUniform("(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))", p.mouseY);
		programShader.setUniform("frameCount", p.frameCount);
		p.quad(-1, -1, 1, -1, 1, 1, -1, 1);
	}

	function compileProgram(p) {
		return `#version 300 es

			precision highp float;

			uniform int width;
			uniform int height;
			uniform int size;
			uniform int error;
			uniform int frameCount;
			uniform int (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
			uniform int (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

			in highp vec2 vPos;
			out vec4 result;

			void main() {
					int scaledWidth = width / size;
					int scaledHeight = height / size;

					// Convert our floating point position from -1 to 1, to an integer position
					// from 0 to width/height
					int x = int((vPos.x + 1.) / 2. * float(scaledWidth));
					int y = int((1. - vPos.y) / 2. * float(scaledHeight));

					if (${p} == 0) {
							result = vec4(1.0, 1.0, 1.0, 1.0);
					} else {
							if (error == 0) {
								result = vec4(0.0, 0.0, 0.0, 1.0);
							} else {
								result = vec4(0.3, 0.0, 0.0, 1.0);
							}
					}
			}
		`;
	}

	const vert = `#version 300 es

	in vec3 aPosition;
	out highp vec2 vPos;

	void main() {
		vPos = (gl_Position = vec4(aPosition, 1.0)).xy;
	}`;
